values = {'a':1,'b':3,'c':3,'d':2,'e':1,'f':4,'g':2,'h':4,'i':1,'j':8,
          'k':5,'l':1,'m':3,'n':1,'o':1,'p':3,'q':10,'r':1,'s':1,'t':1,
          'u':1,'v':4,'w':4,'x':8,'y':4,'z':10}

def word_value(word):
    return sum(values[c] for c in word)

def matches(scrambled, word):
    return sorted(scrambled) == sorted(word)

mode = input().strip()
n = int(input())
groups = [input().strip() for _ in range(n)]
d = int(input())
dictionary = [input().strip() for _ in range(d)]

valid_words = []
for g in groups:
    for w in dictionary:
        if matches(g, w):
            valid_words.append(w)
            break

if mode == "high":
    best = max(word_value(w) for w in valid_words)
else:
    best = min(word_value(w) for w in valid_words)

candidates = sorted(w for w in valid_words if word_value(w) == best)
print(candidates[0])
